from itertools import permutations

# Tuple positions correspond to Reynaldo, Seamus, Theresa, Yuki.
riders = ("Reynaldo", "Seamus", "Theresa", "Yuki")
bikes = ("F", "G", "H", "J")
valid = []

for day1 in permutations(bikes):
    for day2 in permutations(bikes):
        if any(day1[i] == day2[i] for i in range(4)):
            continue
        if "F" in (day1[0], day2[0]):
            continue
        if "J" in (day1[3], day2[3]):
            continue
        if "H" not in (day1[2], day2[2]):
            continue
        if day1[3] != day2[1]:
            continue
        if day1[2] != "J":
            continue
        valid.append((day1, day2))

predicates = {
    "A": lambda d1, d2: d2[0] == "G",
    "B": lambda d1, d2: d1[1] == "H",
    "C": lambda d1, d2: d2[3] == "H",
    "D": lambda d1, d2: "J" in (d1[1], d2[1]),
    "E": lambda d1, d2: "G" in (d1[2], d2[2]),
}

possible = []
print("Exhaustive enumeration: 24 x 24 day assignments")
print("Valid schedules:", len(valid))
for option, predicate in predicates.items():
    witnesses = [(d1, d2) for d1, d2 in valid if predicate(d1, d2)]
    print(option + ":", "could be true" if witnesses else "impossible",
          "| satisfying schedules:", len(witnesses))
    if witnesses:
        possible.append(option)
        d1, d2 = witnesses[0]
        print("  Witness:", {
            rider: (d1[i], d2[i]) for i, rider in enumerate(riders)
        })

submitted = "A"
print("Expected possible options:", possible)
print("Submitted answer:", submitted)
print("CHECK PASS" if possible == [submitted] else "CHECK FAIL")
